<?php require 'config.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_var($_POST['booking_id']??null,FILTER_VALIDATE_INT);$stmt=$pdo->prepare('UPDATE bookings SET status=\'cancelled\' WHERE id=? AND user_id=? AND status=\'confirmed\'');$stmt->execute([$id,$_SESSION['uid']]);flash('Booking cancelled.');go('my_bookings.php');}$stmt=$pdo->prepare('SELECT b.*,t.title FROM bookings b JOIN tours t ON t.id=b.tour_id WHERE b.user_id=? ORDER BY b.id DESC');$stmt->execute([$_SESSION['uid']]);require 'header.php';?><section class="page-head"><h1>My Bookings</h1></section><div class="panel"><div class="tablewrap"><table><thead><tr><th>Tour</th><th>Date</th><th>Visitors</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($stmt as $b):?><tr><td><?=e($b['title'])?></td><td><?=e($b['tour_date'])?></td><td><?=e($b['visitors'])?></td><td><?=e($b['total_price'])?> SAR</td><td><?=e($b['status'])?></td><td><?php if($b['status']==='confirmed'):?><form method="post" onsubmit="return confirm('Cancel this booking?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><button class="smallbtn">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php';?>